1	//! Rendering helpers for REPL/tutorial history entries.
2	//! Extracted from main.rs to keep that module under the
3	//! sw-checklist file-LOC budget.
4	
5	use yew::prelude::*;
6	
7	use mlpl_web_eval::state::{EntryKind, HistoryEntry};
8	use mlpl_web_eval::summary;
9	
10	fn percent_encode(s: &str) -> String {
11	    let mut out = String::with_capacity(s.len());
12	    for b in s.bytes() {
13	        let safe = b.is_ascii_alphanumeric() || matches!(b, b'-' | b'_' | b'.' | b'~');
14	        if safe {
15	            out.push(b as char);
