76	/// `:describe _demo` after a demo run reprints the intro +
77	/// takeaway. Uses MLPL's string-assignment syntax through `eval`
78	/// so the binding goes through the existing string-variable
79	/// surface (Saga 12 step 009) -- no new plumbing.
80	fn bind_demo_metadata(session: &WasmSession, demo: &mlpl_web_demos::Demo) {
81	    let body = format!(
82	        "{}\n\nAbout this demo:\n  {}\n\nTakeaway:\n  {}",
83	        demo.name, demo.intro, demo.takeaway,
84	    );
85	    let escaped = body.replace('\\', "\\\\").replace('"', "\\\"");
86	    let _ = session.eval(&format!("_demo = \"{escaped}\""));
87	}
88	
89	fn push_progress_notes(entries: &mut Vec<HistoryEntry>, demo_name: &str, idx: usize) -> bool {
90	    let mut had = false;
91	    for note in mlpl_web_demos::progress_notes_for(demo_name, idx) {
92	        entries.push(HistoryEntry {
93	            input: note.heading.to_string(),
94	            output: note.body.to_string(),
95	            is_error: false,
96	            kind: EntryKind::Narration,
97	        });
98	        had = true;
99	    }
100	    had
101	}
102	
103	fn schedule_demo_line(
104	    session: Rc<RefCell<WasmSession>>,
105	    history: UseStateHandle<Vec<HistoryEntry>>,
106	    mut entries: Vec<HistoryEntry>,
107	    demo: &'static mlpl_web_demos::Demo,
108	    idx: usize,
109	) {
110	    let lines = demo.lines;
111	    if idx >= lines.len() {
112	        // Last line ran -- append the takeaway narration panel
113	        // and paint the final history state.
114	        entries.push(HistoryEntry {
115	            input: "What just happened".to_string(),
116	            output: demo.takeaway.to_string(),
117	            is_error: false,
118	            kind: EntryKind::Narration,
119	        });
120	        history.set(entries);
121	        return;
122	    }
123	    push_progress_notes(&mut entries, demo.name, idx);
124	    let line = lines[idx];
125	    // Telemetry panel only for SERVER-side lines (browser free to sample):
126	    // MLX/CUDA compute lines, or any `:ask` (LLM runs server-side). Local
127	    // evals block the sampler -> no panel (see docs/worker-threads.md).
128	    #[cfg(target_arch = "wasm32")]
129	    {
130	        let lt = line.trim_start();
131	        let server_side = mlpl_web_eval::eval_url::is_connected()
132	            && (lt.starts_with(":ask")
133	                || (mlpl_web_demos::capability_for(demo.name).requires_connect
134	                    && !lt.starts_with(':')));
135	        mlpl_web_eval::telemetry_trace::begin(server_side);
136	    }
137	    push_running_marker(&mut entries, line);
138	    history.set(entries.clone());
139	    // Connect mode: route the line through the server (so loaded
140	    // demos behave like typed lines -- `:connect list`, `:ask`,
141	    // and bare expressions hit mlpl-serve instead of the local
142	    // session). Falls through to local eval when not connected or
143	    // for non-eligible commands.
144	    #[cfg(target_arch = "wasm32")]
145	    if mlpl_web_eval::eval_url::is_connected()
146	        && dispatch_demo_line_connected(&session, &history, &entries, demo, idx, line)
147	    {
148	        return;
149	    }
150	    run_demo_line_local(session, history, entries, demo, idx, line);
151	}
