153	/// Evaluate one demo line in the local in-process WASM session
154	/// (the non-connect path), in its own `Timeout` tick so the
155	/// browser paints between lines, then recurse to the next line.
156	fn run_demo_line_local(
157	    session: Rc<RefCell<WasmSession>>,
158	    history: UseStateHandle<Vec<HistoryEntry>>,
159	    mut entries: Vec<HistoryEntry>,
160	    demo: &'static mlpl_web_demos::Demo,
161	    idx: usize,
162	    line: &'static str,
163	) {
164	    let session_next = Rc::clone(&session);
165	    let history_next = history.clone();
166	    gloo::timers::callback::Timeout::new(0, move || {
167	        let r = session.borrow().eval_with_values(line);
168	        let is_error = r.display.starts_with("error:");
169	        if !is_error {
170	            let name = line.split('=').next().unwrap_or(line).trim().to_string();
171	            let info = mlpl_web_viz3d::events::build_shape_info_full(
172	                name,
173	                r.shape,
174	                r.values,
175	                r.string_list,
176	                r.viz_node,
177	            );
178	            mlpl_web_viz3d::events::emit(&mlpl_web_viz3d::events::Stage3dEvent {
179	                step_idx: 0,
180	                label: mlpl_eval_core::indent_source(line),
181	                output: info,
182	            });
183	        }
184	        replace_running_with_result(&mut entries, line, r.display);
185	        history.set(entries.clone());
186	        schedule_demo_line(session_next, history_next, entries, demo, idx + 1);
187	    })
188	    .forget();
189	}
190	
191	/// Connect-mode demo line: dispatch to the server and continue the
192	/// demo when the async result lands. Returns false (caller does
193	/// local eval) for lines the server path does not handle.
194	#[cfg(target_arch = "wasm32")]
195	fn dispatch_demo_line_connected(
196	    session: &Rc<RefCell<WasmSession>>,
197	    history: &UseStateHandle<Vec<HistoryEntry>>,
198	    entries: &[HistoryEntry],
199	    demo: &'static mlpl_web_demos::Demo,
200	    idx: usize,
201	    line: &'static str,
202	) -> bool {
203	    let mut entries_c = entries.to_vec();
204	    let hist = history.clone();
205	    let sess = Rc::clone(session);
206	    // This demo line's telemetry generation (begin()'d before its marker).
207	    let gen_id = mlpl_web_eval::telemetry_trace::current_gen();
208	    let cont: mlpl_web_eval::eval::ResultCb = Box::new(move |display: String| {
209	        // Persist the backend-load sparkline below a server-run demo line
210	        // so a brief GPU blip survives the marker being replaced.
211	        let out = match (
212	            display.starts_with("error:"),
213	            mlpl_web_eval::telemetry_trace::summary(gen_id),
214	        ) {
215	            (false, Some(tel)) => format!("{display}\n{tel}"),
216	            _ => display,
217	        };
218	        replace_running_with_result(&mut entries_c, line, out);
219	        hist.set(entries_c.clone());
220	        schedule_demo_line(sess, hist.clone(), entries_c, demo, idx + 1);
221	    });
222	    // Connect-only demos (MLX/CUDA tier) run their heavy lines on the
223	    // server so the browser main thread stays responsive (no "page
224	    // unresponsive" freeze) and the GPU does the work. CPU-tier demos
225	    // route only :ask/:models and keep plain lines local (3D).
226	    let route_all = mlpl_web_demos::capability_for(demo.name).requires_connect;
227	    crate::connect::dispatch_demo_line(line, entries, route_all, cont)
228	}
