[package]
name = "mlpl-web-eval"
edition.workspace = true
license.workspace = true
version.workspace = true

# Saga 32 step 004: web-side eval-pipeline extracted from
# apps/mlpl-web. Hosts the 4 eval-shaped modules (eval, eval_url,
# eval_wasm, eval_sse) plus state.rs (HistoryEntry / DocTab) and
# summary.rs (numeric-output summarizer). Clean DAG leaf: no
# imports from mlpl-web crates; only external (mlpl-wasm + the
# WASM-side fetch / future stack).

[dependencies]
mlpl-wasm = { path = "../mlpl-wasm" }
# Phase 1c: emit a 3D sculpture from a connect-mode eval response
# (shape/values now ride back from mlpl-serve). No cycle: viz3d does
# not depend on this crate.
mlpl-web-viz3d = { path = "../../../web-viz3d/crates/mlpl-web-viz3d" }
mlpl-web-viz-ir = { path = "../../../web-viz-ir/crates/mlpl-web-viz-ir" }
# Shared /v1/stats wire type + its pure rendering (:status report,
# sparklines). Serde-only leaf from the monitoring component; compiles
# to WASM. Downward dep only -- no cycle.
mlpl-monitor-types = { path = "../../../monitoring/crates/mlpl-monitor-types" }
gloo = { version = "0.11", features = ["net", "timers", "futures"] }
serde_json = "1"
serde = { version = "1", features = ["derive"] }
wasm-bindgen-futures = "0.4"
# Racing a fetch against a timeout so a wedged/absent connect server
# fails fast instead of hanging the REPL.
futures = "0.3"
web-sys = { version = "0.3", features = [
    "Document",
    "Element",
    "Window",
    "console",
] }

