110	/// Saga 29 step 018: recursive Timeout-yielding eval loop for
111	/// REPL submissions. Pushes a Running marker, yields, evals,
112	/// replaces marker with result, recurses to next line.
113	pub(crate) fn process_next_eval(
114	    deps: EvalDeps,
115	    mut history: Vec<HistoryEntry>,
116	    queue: Vec<String>,
117	    idx: usize,
118	) {
119	    if idx >= queue.len() {
120	        deps.history.set(history);
121	        return;
122	    }
123	    let line = queue[idx].clone();
124	    // Decide telemetry remoteness BEFORE the marker renders, so the live
125	    // panel only mounts for server-side evals (not browser-local ones).
126	    #[cfg(target_arch = "wasm32")]
127	    crate::connect::begin_eval_telemetry(&line, &history);
128	    crate::running::push_running_marker(&mut history, &line);
129	    deps.history.set(history.clone());
130	    // Connect mode (?connect=<url>): `:connect list` lists the
131	    // server's Ollama models; real expressions + the `:ask`
132	    // shortcut route to mlpl-serve (async, server-side) so the
133	    // browser never blocks. Each returns true when it took the line.
134	    // A pending `:reset` confirmation (armed on the previous line) wins
135	    // over every other interpretation of this line -- so the y/N answer
136	    // is never lexed as MLPL.
137	    #[cfg(target_arch = "wasm32")]
138	    if crate::connect::try_reset_answer(&deps, &history, &queue, idx, &line) {
139	        return;
140	    }
141	    #[cfg(target_arch = "wasm32")]
142	    if crate::connect::try_ollama_models(&deps, &history, &queue, idx, &line) {
143	        return;
144	    }
145	    #[cfg(target_arch = "wasm32")]
146	    if crate::connect::try_status(&deps, &history, &queue, idx, &line) {
147	        return;
148	    }
149	    #[cfg(target_arch = "wasm32")]
150	    if crate::connect::try_reset(&deps, &history, &queue, idx, &line) {
151	        return;
152	    }
153	    #[cfg(target_arch = "wasm32")]
154	    if crate::connect::try_connect_eval(&deps, &history, &queue, idx, &line) {
155	        return;
156	    }
157	    let deps_next = deps.clone();
158	    let queue_next = queue.clone();
159	    gloo::timers::callback::Timeout::new(0, move || {
160	        let entry = eval_one_line_with_3d(&deps_next, &line);
161	        history.pop();
162	        history.push(entry);
163	        process_next_eval(deps_next, history, queue_next, idx + 1);
164	    })
165	    .forget();
166	}
