195	fn eval_one_line_with_3d(deps: &EvalDeps, line: &str) -> HistoryEntry {
196	    if line == ":help" || line.starts_with(':') {
197	        return eval_one_line(deps, line);
198	    }
199	    #[cfg(target_arch = "wasm32")]
200	    {
201	        let r = deps.session.borrow().eval_with_values(line);
202	        let is_error = r.display.starts_with("error:");
203	        if !is_error {
204	            let name = line.split('=').next().unwrap_or(line).trim().to_string();
205	            let info = mlpl_web_viz3d::events::build_shape_info_full(
206	                name,
207	                r.shape,
208	                r.values,
209	                r.string_list,
210	                r.viz_node,
211	            );
212	            mlpl_web_viz3d::events::emit(&mlpl_web_viz3d::events::Stage3dEvent {
213	                step_idx: 0,
214	                label: mlpl_eval_core::indent_source(line),
215	                output: info,
216	            });
217	        }
218	        return HistoryEntry {
219	            input: line.to_string(),
220	            output: r.display,
221	            is_error,
222	            kind: EntryKind::Command,
223	        };
224	    }
225	    #[cfg(not(target_arch = "wasm32"))]
226	    eval_one_line(deps, line)
227	}
