229	/// `:history` output -- the recent REPL command lines, so the
230	/// user (and the `:ask` LLM, which also receives this) can see
231	/// what has been run.
232	fn history_listing(deps: &EvalDeps) -> String {
233	    let lines: Vec<String> = deps
234	        .history
235	        .iter()
236	        .filter(|e| matches!(e.kind, EntryKind::Command))
237	        .map(|e| format!("mlpl> {}", e.input.trim()))
238	        .collect();
239	    if lines.is_empty() {
240	        "(no commands run yet)".to_string()
241	    } else {
242	        lines.join("\n")
243	    }
244	}
245	
246	/// Shown for `:ask` when there is no connected server (e.g. the
247	/// public live demo). `:ask` needs a server to reach an LLM, so we
248	/// give a clear notice instead of lexing the question as MLPL
249	/// (which errors on punctuation like `?`).
250	const ASK_NEEDS_SERVER: &str = "`:ask` is not available on the public demo -- it needs a connected mlpl-serve with Ollama running. Run `mlpl-serve` on a local machine (with `ollama serve`), then open this REPL with `?connect=<server-url>` appended to the page URL (e.g. `...?connect=http://host:6464`). The CUDA / MLX demos additionally need that server on a host with the matching GPU (Linux+NVIDIA for CUDA, Apple Silicon for MLX).";
251	
252	/// Shown for `:status` when no server is connected. Connect mode
