        return connect_eval(program, on_result);
    }
    let Some(url) = current_connect_url_from_window() else {
        return false;
    };
    if let Some(reason) = crate::connect_guard::connect_blocked_reason() {
        on_result(format!("error: {reason}"));
        return true;
    }
    // This eval's generation: metric frames land in ITS loss trace, so
    // a concurrent eval/watch never intermixes curves.
    let gen_id = crate::telemetry_trace::current_gen();
    CONNECT_EVALUATOR.with(|cell| {
        if cell.borrow().is_none() {
            *cell.borrow_mut() = Some(RemoteEvaluator::new(url));
        }
        cell.borrow().as_ref().expect("evaluator set above").eval_stream(
            program,
            Box::new(move |m| crate::loss_trace::push(gen_id, &m.name, m.value)),
            Box::new(move |outcome| on_result(outcome.into_display().0)),
        );
    });
    true
}

impl Evaluator for RemoteEvaluator {
    fn eval(&self, program: &str, on_result: ResultCb) {
        let base = self.base_url().to_string();
        let state = self.state_handle();
        let program = program.to_string();
        wasm_bindgen_futures::spawn_local(async move {
            let result = wasm_eval(&base, &state, &program).await;
            on_result(result);
        });
    }
    fn clear(&self) {
        self.clear_state();
    }
}

async fn wasm_eval(
    base_url: &str,
    state: &std::cell::RefCell<Option<crate::eval::RemoteSession>>,
    program: &str,
) -> String {
    if state.borrow().is_none() {
        match wasm_create_session(base_url).await {
            Ok(s) => *state.borrow_mut() = Some(s),
            Err(e) => return format!("error: {e}"),
        }
    }
    let s = state
        .borrow()
        .as_ref()
        .expect("session created above")
        .clone();
    let url = format!(
        "{}/v1/sessions/{}/eval",
        base_url.trim_end_matches('/'),
        s.session_id
    );
    let req = match gloo::net::http::Request::post(&url)
        .header("Authorization", &format!("Bearer {}", s.token))
        .header("Content-Type", "application/json")
        .body(serde_json::json!({"program": program}).to_string())
    {
        Ok(r) => r,
        Err(e) => return format!("error: {e}"),
    };
    // Generous deadline: a connect eval can legitimately run minutes --
    // a CPU base-pretrain step (e.g. the CUDA LoRA demo's `train 40` over
    // the full corpus) or a GPU fine-tune. Match mlpl-serve's own 600s
    // peer-forward timeout (peers.rs PEER_TIMEOUT_SECS) so the client never
    // gives up before the server would. The short 6s session-creation
    // deadline (eval_wasm_helpers.rs) is the real "is the backend up?"
    // fail-fast; once a session exists, long compute is expected.
    let resp = match with_deadline(600_000, "eval", async {
        req.send().await.map_err(|e| e.to_string())
    })
    .await
    {
        Ok(r) => r,
        Err(e) => return format!("error: {e}"),
    };
    let body: serde_json::Value = match resp.json().await {
        Ok(j) => j,
        Err(e) => return format!("error: decode: {e}"),
    };
    if let Some(err) = body.get("error").and_then(|v| v.as_str()) {
        return format!("error: {err}");
    }
    // Phase 1c: emit a 3D sculpture from the response's viz data so
    // server-evaluated results populate the 3D view too.
    crate::connect_viz::emit_from_response(program, &body);
    body.get("value")
        .and_then(|v| v.as_str())
        .map_or_else(|| format!("error: missing value: {body}"), str::to_string)
}

impl RemoteEvaluator {
    /// Browser streaming-eval. Spawns a local future that POSTs
    /// to `/eval_stream`, reads the response body as a UTF-8
    /// stream, parses SSE frames, fires `on_metric` per metric,
    /// and finally fires `on_result` with the terminal outcome.
    pub fn eval_stream(&self, program: &str, on_metric: MetricCb, on_result: StreamCb) {
        let base = self.base_url().to_string();
        let state = self.state_handle();
        let program = program.to_string();
        wasm_bindgen_futures::spawn_local(async move {
            let outcome = wasm_eval_stream(&base, &state, &program, on_metric).await;
            on_result(outcome);
        });
    }

    /// Browser cancel: fire `/v1/sessions/<id>/cancel`. No-op
    /// when no session has been minted yet.
    pub fn cancel(&self) {
        let Some(session_id) = self.current_session_id() else {
            return;
        };
        let Some(token) = self.current_token() else {
            return;
        };
        let url = format!(
            "{}/v1/sessions/{}/cancel",
            self.base_url().trim_end_matches('/'),
            session_id
        );
        wasm_bindgen_futures::spawn_local(async move {
            if let Ok(req) = gloo::net::http::Request::post(&url)
                .header("Authorization", &format!("Bearer {token}"))
                .body(String::new())
            {
                let _ = req.send().await;
            }
        });
    }

    /// Browser viz fetch: `GET /v1/viz/<id>` with bearer auth.
    /// Returns `(bytes, content_type)` so the caller can render
    /// an `<img>` (for `image/*`) or an `<iframe srcdoc>` (for
    /// `text/html`). Native equivalent lives in `eval.rs`.
    pub async fn fetch_viz_async(
        &self,
        viz_url: &str,
        bearer: &str,
    ) -> Result<(Vec<u8>, String), String> {
        let url = crate::eval::resolve_viz_url(self.base_url(), viz_url);
        let resp = gloo::net::http::Request::get(&url)
            .header("Authorization", &format!("Bearer {bearer}"))
            .send()
            .await
            .map_err(|e| e.to_string())?;
        if !resp.ok() {
            return Err(format!("fetch_viz: {}", resp.status()));
        }
        let content_type = resp
            .headers()
            .get("content-type")
            .unwrap_or_else(|| "application/octet-stream".to_string());
        let bytes = resp.binary().await.map_err(|e| e.to_string())?;
        Ok((bytes, content_type))
    }
}

