11	pub fn make_run_demo(
12	    session: Rc<RefCell<WasmSession>>,
13	    history: UseStateHandle<Vec<HistoryEntry>>,
14	) -> Callback<usize> {
15	    Callback::from(move |idx: usize| {
16	        let Some(demo) = DEMOS.get(idx) else {
17	            return;
18	        };
19	        session.borrow().clear();
20	        let _ = js_sys::eval("window.__stage3d_clear && window.__stage3d_clear()");
21	        // Lead with a narration panel framing what the demo does
22	        // and why. Demo lines follow; the takeaway narration lands
23	        // after the final line in `schedule_demo_line`. Also bind
24	        // a `_demo` string in the session so `:describe _demo`
25	        // prints the intro + takeaway from the REPL.
26	        bind_demo_metadata(&session.borrow(), demo);
27	        let intro_entry = HistoryEntry {
28	            input: format!("About this demo -- {}", demo.name),
29	            output: intro_with_literate_link(demo),
30	            is_error: false,
31	            kind: EntryKind::Narration,
32	        };
33	        let entries = vec![intro_entry];
34	        history.set(entries.clone());
35	        // Evaluate demo lines asynchronously: each line runs in
36	        // its own `Timeout::new(0, ...)` tick so the browser can
37	        // paint the preceding line's output and process input
38	        // between lines. A long-running single line (e.g. `train
39	        // 30 { ... }`) still blocks the event loop *during* its
40	        // own eval -- fixing that needs Web Workers (see
41	        // docs/worker-threads.md) -- but the cross-line yield
42	        // keeps the tab from triggering the "unresponsive"
43	        // dialog on multi-line demos where the total wall clock
44	        // is the problem.
45	        //
46	        // We thread the accumulated `entries` vec through
47	        // recursion explicitly rather than reading from the
48	        // `UseStateHandle` inside each tick: a state handle is
49	        // snapshotted at the callback's closure-creation time
50	        // and does not refresh between `set()` calls, so reading
51	        // via `(*history).clone()` inside a deferred Timeout
52	        // reliably sees the stale initial value and each tick
53	        // overwrites the previous one's write. Passing `entries`
54	        // by move keeps a single authoritative Rust-side source
55	        // of truth; `history.set(entries.clone())` is purely for
56	        // the UI paint.
57	        schedule_demo_line(session.clone(), history.clone(), entries, demo, 0);
58	    })
59	}
60	
61	/// The demo intro, with a "literate walkthrough" link appended when
62	/// the demo has a companion org-mode HTML (bundled under `literate/`).
63	/// For connect-only demos the link is the way to see what the demo
64	/// does without a server -- the page is a real recorded run.
65	fn intro_with_literate_link(demo: &mlpl_web_demos::Demo) -> String {
66	    match mlpl_web_demos::literate_for(demo.name) {
67	        Some(file) => format!(
68	            "{}\n\n[Emacs Org-mode literate walkthrough](literate/{file}) -- every step run and explained, with the before/after chart.",
69	            demo.intro
70	        ),
71	        None => demo.intro.to_string(),
72	    }
73	}
