75	/// Bind `_demo` as a string variable in the session so typing
76	/// `:describe _demo` after a demo run reprints the intro +
77	/// takeaway. Uses MLPL's string-assignment syntax through `eval`
78	/// so the binding goes through the existing string-variable
79	/// surface (Saga 12 step 009) -- no new plumbing.
80	fn bind_demo_metadata(session: &WasmSession, demo: &mlpl_web_demos::Demo) {
81	    let body = format!(
82	        "{}\n\nAbout this demo:\n  {}\n\nTakeaway:\n  {}",
83	        demo.name, demo.intro, demo.takeaway,
84	    );
85	    let escaped = body.replace('\\', "\\\\").replace('"', "\\\"");
86	    let _ = session.eval(&format!("_demo = \"{escaped}\""));
87	}
