1	//! Saga 21.5 step 008: shared SSE wire-frame parser.
2	//!
3	//! `parse_sse_stream` reads the response body line-by-line and
4	//! dispatches assembled `event:`/`data:` frames through
5	//! `dispatch_sse_frame` to either the `on_metric` callback (for
6	//! `event: metric`), a terminal `StreamOutcome::Done` (for
7	//! `event: done`), `Cancelled` (for `event: cancelled`), or
8	//! `Error` (for `event: error` or malformed payloads).
9	//!
10	//! Lives in its own module so the native + WASM impls of
11	//! `RemoteEvaluator::eval_stream` can share one implementation
12	//! without inflating `eval.rs` over its 500-line file budget.
13	
14	use crate::eval::{MetricCb, RemoteMetric, StreamOutcome};
15	
16	/// Consume an SSE response body via a `BufRead` line iterator
17	/// and return the terminal outcome once a `done` / `cancelled`
18	/// / `error` frame arrives. The native impl wraps a
19	/// `reqwest::blocking::Response`; the WASM streaming impl feeds
20	/// `ReadableStream` chunks through [`SseFeed`] directly.
21	pub fn parse_sse_stream<R: std::io::BufRead>(reader: R, on_metric: &mut MetricCb) -> StreamOutcome {
22	    let mut feed = SseFeed::default();
23	    for line in reader.lines() {
24	        let line = match line {
25	            Ok(l) => l,
26	            Err(e) => {
27	                return StreamOutcome::Error {
28	                    message: format!("stream read: {e}"),
29	                };
30	            }
31	        };
32	        if let Some(outcome) = feed.push(format!("{line}\n").as_bytes(), on_metric) {
33	            return outcome;
34	        }
35	    }
36	    StreamOutcome::Error {
37	        message: "stream ended without terminal frame".into(),
38	    }
39	}
40	
41	/// Push-based twin of [`parse_sse_stream`] for the browser
42	/// `ReadableStream` path: chunks arrive at arbitrary byte boundaries
43	/// (mid-line, mid-frame, mid-UTF-8), get buffered until a full line is
44	/// available, and completed frames dispatch exactly like the pull
45	/// parser's. Connect-telemetry step 002.
46	#[derive(Default)]
47	pub struct SseFeed {
48	    buf: Vec<u8>,
49	    event: Option<String>,
50	    data: Option<String>,
51	}
52	
53	impl SseFeed {
54	    /// Feed one chunk of SSE body bytes. Fires `on_metric` per
55	    /// completed `event: metric` frame; returns the terminal outcome
56	    /// once a `done` / `cancelled` / `error` frame completes.
57	    pub fn push(&mut self, chunk: &[u8], on_metric: &mut MetricCb) -> Option<StreamOutcome> {
58	        self.buf.extend_from_slice(chunk);
59	        while let Some(nl) = self.buf.iter().position(|&b| b == b'\n') {
60	            let raw: Vec<u8> = self.buf.drain(..=nl).collect();
61	            let line = String::from_utf8_lossy(&raw);
62	            if let Some(outcome) = self.take_line(line.trim_end_matches(['\n', '\r']), on_metric) {
63	                return Some(outcome);
64	            }
65	        }
66	        None
67	    }
68	
69	    /// One complete line: blank dispatches the assembled frame,
70	    /// `event:` / `data:` prefixes accumulate into it.
71	    fn take_line(&mut self, line: &str, on_metric: &mut MetricCb) -> Option<StreamOutcome> {
72	        if line.is_empty() {
73	            return dispatch_sse_frame(self.event.take(), self.data.take(), on_metric);
74	        }
75	        if let Some(rest) = line.strip_prefix("event:") {
76	            self.event = Some(rest.trim().to_string());
77	        } else if let Some(rest) = line.strip_prefix("data:") {
78	            self.data = Some(rest.trim().to_string());
79	        }
80	        None
81	    }
82	}
83	
84	impl StreamOutcome {
85	    /// Collapse a terminal stream outcome into the REPL's
86	    /// `(display, is_error)` convention (errors as `"error: ..."`
87	    /// text), so streaming call sites plug into the same history
88	    /// entries the non-streaming path produces.
89	    #[must_use]
90	    pub fn into_display(self) -> (String, bool) {
91	        match self {
92	            Self::Done { value, .. } => (value, false),
93	            Self::Cancelled {
94	                step,
95	                partial_losses,
96	            } => (
97	                format!(
98	                    "cancelled at step {step} ({} partial loss points kept)",
99	                    partial_losses.len()
100	                ),
101	                false,
102	            ),
103	            Self::Error { message } => (format!("error: {message}"), true),
104	        }
105	    }
106	}
107	
108	fn dispatch_sse_frame(
109	    event: Option<String>,
110	    data: Option<String>,
111	    on_metric: &mut MetricCb,
112	) -> Option<StreamOutcome> {
113	    let (Some(event), Some(data)) = (event, data) else {
114	        return None;
115	    };
116	    let v: serde_json::Value = serde_json::from_str(&data).ok()?;
117	    if event == "metric" {
118	        on_metric(&RemoteMetric {
119	            name: v.get("name").and_then(|x| x.as_str())?.to_string(),
120	            step: v.get("step")?.as_u64()? as usize,
121	            value: v.get("value")?.as_f64()?,
122	        });
123	        return None;
124	    }
125	    terminal_outcome(&event, &v)
126	}
127	
128	/// A `done` / `cancelled` / `error` frame's terminal outcome (`None`
129	/// for `ready` and unknown events).
130	fn terminal_outcome(event: &str, v: &serde_json::Value) -> Option<StreamOutcome> {
131	    match event {
132	        "done" => Some(StreamOutcome::Done {
133	            value: v.get("value").and_then(|x| x.as_str())?.to_string(),
134	            kind: v.get("kind").and_then(|x| x.as_str())?.to_string(),
135	        }),
136	        "cancelled" => Some(StreamOutcome::Cancelled {
137	            step: v.get("step")?.as_u64()? as usize,
138	            partial_losses: v
139	                .get("partial_losses")?
140	                .as_array()?
141	                .iter()
142	                .filter_map(serde_json::Value::as_f64)
143	                .collect(),
144	        }),
145	        "error" => Some(StreamOutcome::Error {
146	            message: v
147	                .get("error")
148	                .and_then(|x| x.as_str())
149	                .unwrap_or("unknown error")
150	                .to_string(),
151	        }),
152	        _ => None,
153	    }
154	}

