38	/// The compact MLPL reference for the `:ask` system prompt: the syntax
39	/// cheat-sheet plus every builtin's signature, grouped, sourced from the
40	/// curated `BUILTIN_GROUPS` table so it never drifts from the real set.
41	fn mlpl_reference() -> String {
42	    let mut r = MLPL_SYNTAX.to_string();
43	    for (group, entries) in mlpl_eval_core::inspect_groups::BUILTIN_GROUPS {
44	        let sigs: Vec<&str> = entries.iter().map(|&(_, sig, _)| sig).collect();
45	        r.push_str(&format!(" [{group}] {}.", sigs.join(", ")));
46	    }
47	    r
48	}
49	
50	/// Summarize the recent REPL activity (last few command/result
51	/// pairs) so `:ask` can answer questions about "what is being run
52	/// in the REPL" -- an in-context REPL assistant. Newest entries
53	/// are kept; long outputs are truncated char-safely.
54	fn repl_history_context(history: &[HistoryEntry]) -> String {
55	    let mut recent: Vec<String> = history
56	        .iter()
57	        .rev()
58	        .filter(|e| matches!(e.kind, EntryKind::Command))
59	        .take(6)
60	        .map(|e| {
61	            let out: String = e.output.trim().chars().take(180).collect();
62	            format!("mlpl> {} => {}", e.input.trim(), out)
63	        })
64	        .collect();
65	    recent.reverse();
66	    recent.join(" | ")
67	}
