72	/// follow far better. The question is sent as the user prompt.
73	fn build_ask_system(history: &[HistoryEntry]) -> String {
74	    let mut p = ASK_SYSTEM.to_string();
75	    // Compact MLPL reference (syntax + builtin signatures) -- real forms.
76	    p.push_str(&mlpl_reference());
77	    // Ground the model in the active demo (its "About this demo -- <name>"
78	    // narration names the task, e.g. tic-tac-toe) so it doesn't guess Othello.
79	    if let Some(intro) = history
80	        .iter()
81	        .rev()
82	        .find(|e| matches!(e.kind, EntryKind::Narration) && e.input.starts_with("About this demo"))
83	    {
84	        let body: String = intro.output.trim().chars().take(400).collect();
85	        p.push_str(&format!(" Active demo -- {}: {body}.", intro.input.trim()));
86	    }
87	    let recent = repl_history_context(history);
88	    if !recent.is_empty() {
89	        p.push_str(&format!(" Recent REPL activity (oldest first): {recent}."));
90	    }
91	    let sel = crate::context::selection_context();
92	    if !sel.is_empty() {
93	        p.push_str(&format!(" Selected 3D sculpture: {sel}."));
94	    }
95	    p
96	}

