19	/// Stream `program` on `evaluator`, landing each metric frame in
20	/// generation `gen_id`'s loss trace and the terminal outcome on
21	/// `on_result` as a display string. The glue between
22	/// `connect_eval_auto` and the live loss panel.
23	pub(crate) fn stream_into_loss_trace(
24	    evaluator: &RemoteEvaluator,
25	    program: &str,
26	    gen_id: u32,
27	    on_result: ResultCb,
28	) {
29	    evaluator.eval_stream(
30	        program,
31	        Box::new(move |m| crate::loss_trace::push(gen_id, &m.name, m.value)),
32	        Box::new(move |outcome| on_result(outcome.into_display().0)),
