48	// Inner helper returning `Result` so `?` collapses the fallible
49	// `gloo::net::http` steps into one error path.
50	async fn wasm_eval_stream_inner(
51	    base_url: &str,
52	    state: &RefCell<Option<RemoteSession>>,
53	    program: &str,
54	    on_metric: &mut MetricCb,
55	) -> Result<StreamOutcome, String> {
56	    if state.borrow().is_none() {
57	        *state.borrow_mut() = Some(wasm_create_session(base_url).await?);
58	    }
59	    let s = state.borrow().as_ref().expect("session").clone();
60	    let resp = post_stream_request(base_url, &s, program).await?;
61	    if resp.ok() {
62	        read_sse_stream(&resp, on_metric).await
63	    } else {
64	        Ok(StreamOutcome::Error {
65	            message: resp.text().await.unwrap_or_default(),
66	        })
67	    }
68	}
