70	/// POST the `/eval_stream` request (bearer-authed JSON body).
71	async fn post_stream_request(
72	    base_url: &str,
73	    s: &RemoteSession,
74	    program: &str,
75	) -> Result<gloo::net::http::Response, String> {
76	    let url = format!(
77	        "{}/v1/sessions/{}/eval_stream",
78	        base_url.trim_end_matches('/'),
79	        s.session_id
80	    );
81	    gloo::net::http::Request::post(&url)
82	        .header("Authorization", &format!("Bearer {}", s.token))
83	        .header("Content-Type", "application/json")
84	        .body(serde_json::json!({"program": program}).to_string())
85	        .map_err(|e| e.to_string())?
86	        .send()
87	        .await
88	        .map_err(|e| e.to_string())
89	}
