103	        .get_reader()
104	        .dyn_into()
105	        .map_err(|_| "no stream reader".to_string())?;
106	    let mut feed = SseFeed::default();
107	    loop {
108	        let chunk = wasm_bindgen_futures::JsFuture::from(reader.read())
109	            .await
110	            .map_err(|_| "stream read failed".to_string())?;
111	        let Some(bytes) = chunk_bytes(&chunk)? else {
112	            let message = "stream ended without terminal frame".to_string();
113	            return Ok(StreamOutcome::Error { message });
114	        };
115	        if let Some(outcome) = feed.push(&bytes, on_metric) {
116	            return Ok(outcome);
117	        }
118	    }
119	}
120	
121	/// One `reader.read()` result -> its `Uint8Array` bytes, or `None`
122	/// when the stream reports done.
123	fn chunk_bytes(chunk: &wasm_bindgen::JsValue) -> Result<Option<Vec<u8>>, String> {
124	    let done = js_sys::Reflect::get(chunk, &"done".into())
125	        .ok()
126	        .and_then(|v| v.as_bool())
127	        .unwrap_or(true);
128	    if done {
129	        return Ok(None);
130	    }
131	    let value = js_sys::Reflect::get(chunk, &"value".into())
132	        .map_err(|_| "stream chunk missing value".to_string())?;
133	    Ok(Some(js_sys::Uint8Array::new(&value).to_vec()))
134	}

